python3 -c "
import json
d = json.load(open('/home/arrenchulz/.openclaw/exec-approvals.json'))
agents = d.get('agents', {})
all_patterns = []
for scope, v in agents.items():
    for entry in v.get('allowlist', []):
        all_patterns.append((scope, entry['pattern']))

blocked = ['**', '/usr/bin/bash', '/bin/bash', '/bin/sh', '/usr/bin/cp', '/usr/bin/mv', '/usr/bin/mkdir', '/mnt/c']
print('=== checking for removed entries ===')
for scope, p in all_patterns:
    for b in blocked:
        if b in p:
            print(f'  FOUND (should be absent): {scope} -> {p}')

print()
print('=== current allowlist ===')
for scope, p in all_patterns:
    print(f'  {scope}: {p}')
"

